mapper.select:
select m.member_id, m.phone, m.nickname, m.province, m.city, m.district, m.referrer_id, m.referrer_path, m.direct_seq, m.level, m.vip_expire_at, m.balance, m.frozen, m.green_points, m.status, m.remark, m.create_time, m.update_time, r.nickname as referrer_name, r.phone as referrer_phone, (select count(1) from hys_member c where c.referrer_id = m.member_id) as direct_count, (select count(1) from hys_member c where c.referrer_path like concat(m.referrer_path, m.member_id, ',%') and c.member_id <> m.member_id) as team_count, (select coalesce(sum(k.amount), 0) from hys_commission k where k.member_id = m.member_id and k.status = 1) as commission_total from hys_member m left join hys_member r on r.member_id = m.referrer_id
and m.phone like concat('%', #{phone}, '%') and m.nickname like concat('%', #{nickname}, '%') and m.level = #{level} and m.status = #{status} and m.referrer_id = #{referrerId}
and m.create_time >= #{params.beginTime}
and m.create_time <= concat(#{params.endTime}, ' 23:59:59')
order by m.member_id asc

mapper.update:
update hys_member
nickname = #{nickname}, province = #{province}, city = #{city}, district = #{district}, level = #{level}, status = #{status}, remark = #{remark}, update_time = now()
where member_id = #{memberId}

update hys_member
set level = #{level}, vip_expire_at = #{vipExpireAt}, update_time = now()
where member_id = #{memberId}

update hys_member
set password = #{password}, token_version = token_version + 1, update_time = now()
where member_id = #{memberId}

update hys_member
set balance = balance + #{delta}, update_time = now()
where member_id = #{memberId}

update hys_member
set balance = balance - #{amount}, frozen = frozen + #{amount}, update_time = now()
where member_id = #{memberId} and balance >= #{amount}

update hys_member
set balance = balance + #{amount}, frozen = frozen - #{amount}, update_time = now()
where member_id = #{memberId} and frozen >= #{amount}

update hys_member
set frozen = frozen - #{amount}, update_time = now()
where member_id = #{memberId} and frozen >= #{amount}
